-- Keep existing product IDs and prices; preserve historic order snapshots.
begin;
update public.bumpr_products set name = 'BUMPR HYDRO-COAT', description = 'Keramische coating in een glazen flesje met druppelpipet, inclusief applicatorspons en suèdedoekje.' where slug = 'ceramic-coating';
update public.bumpr_products set description = 'Polijstmiddel in een fles met push-pull-dop: trek de dop uit om te openen en druk hem in om te sluiten.' where slug = 'polish';
update public.bumpr_products set description = 'Polish (500 ml), Fast Detailer (500 ml) en HYDRO-COAT in een glazen flesje met druppelpipet. Inclusief applicatorspons en suèdedoekje.' where slug = 'performance-set';
insert into public.bumpr_products (slug, name, description, price_cents, size_ml, is_bundle, sort_order, is_available) values ('iron-remover', 'BUMPR Iron Remover Wheel Cleaner', 'Iron Remover Wheel Cleaner in een spuitfles, met de herkenbare paarse BUMPR-accenten.', 1695, null, false, 5, true) on conflict (slug) do update set name = excluded.name, description = excluded.description, price_cents = excluded.price_cents, size_ml = excluded.size_ml, is_bundle = excluded.is_bundle, sort_order = excluded.sort_order, is_available = excluded.is_available;
insert into public.bumpr_products (slug, name, description, price_cents, size_ml, is_bundle, sort_order, is_available) values ('microvezel-droogdoeken', 'BUMPR Microvezeldoeken — set van 3', 'Drie zwarte microvezeldoeken van 40 × 40 cm en 400 GSM, met oranje BUMPR-borduring en oranje randen.', 4995, null, false, 6, true) on conflict (slug) do update set name = excluded.name, description = excluded.description, price_cents = excluded.price_cents, size_ml = excluded.size_ml, is_bundle = excluded.is_bundle, sort_order = excluded.sort_order, is_available = excluded.is_available;
commit;
